"""Freezes the startup set, so nothing is read from a filesystem to boot.

Decision 0046 wants a worker that has a standard library and no filesystem.
`runtime/taffy_stdlib_boot.py` is what serves the library out of a mapped
descriptor, but it cannot be the first thing that runs: CPython needs a codec
and a handful of pure-Python modules before it can execute anything at all, and
on a stock build it reads those from a path.

This tool removes that path. It marshals the bootstrap and the startup set into
a C table an embedder assigns to `PyImport_FrozenModules`, which is the
documented way for an embedding application to add frozen modules. With the
table in place and `PyConfig.module_search_paths_set` on an empty list, an
interpreter starts, imports and runs having never looked at a directory.

Two rules are worth stating because breaking either produces a binary that
starts and then fails in a way that names the wrong thing:

  * **The marshalling interpreter must be the pinned one.** A code object
    marshalled by a different CPython is a different format; the resulting
    binary crashes on its first frozen import with an error about the module,
    not about the mismatch. The tool compares versions and refuses.
  * **The table is appended, never substituted.** CPython's own frozen table
    carries `importlib`, and an embedder that replaces the pointer rather than
    joining the two removes the machinery every import goes through. The
    joining is the embedder's, and this tool emits only the extra rows so the
    substitution cannot be written by accident.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import runpy
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
RUNTIME = os.path.join(os.path.dirname(HERE), "runtime")

#: First-party modules frozen into the executable.  The entrypoint module is
#: beside the bootstrap deliberately: an archive handed to the worker may
#: provide library code, but can never replace the dispatch table.
FIRST_PARTY_MODULES = {
    "taffy_stdlib_boot": "taffy_stdlib_boot.py",
    "taffy_python_tools": "taffy_python_tools.py",
}

#: Everything else frozen, as a path under a CPython `Lib/` and the reason it
#: is here. Each was observed being imported before the bootstrap could take
#: over; a name added without that observation is weight nobody measured.
STARTUP_MODULES = {
    "encodings": ("encodings/__init__.py", "the codec registry, imported before any user code"),
    "encodings.aliases": ("encodings/aliases.py", "the alias table `encodings` reads at import"),
    "encodings.utf_8": ("encodings/utf_8.py", "the default source and filesystem codec"),
    "encodings.ascii": ("encodings/ascii.py", "the fallback codec when a locale names none"),
    "encodings.latin_1": ("encodings/latin_1.py", "the surrogate-free byte codec errors fall back to"),
    "_android_support": ("_android_support.py", "CPython's own Android start-up, which redirects the streams into the system log"),
    "_weakrefset": ("_weakrefset.py", "imported by `threading` below, and by `abc` before it"),
    "threading": ("threading.py", "imported during interpreter start-up, not by anything here"),
    "types": ("types.py", "imported by the import machinery itself"),
}

#: Packages, which need `is_package` set so a submodule of them resolves.
PACKAGES = frozenset({"encodings"})

#: The child program that does the marshalling. It runs under the pinned
#: CPython rather than under whatever host Python the tool suite found, because
#: the marshal format belongs to the interpreter the bytes will be read by.
_CHILD = r'''
import json, marshal, sys

spec = json.load(open(sys.argv[1]))
rows, blocks = [], []
for name, entry in spec.items():
    with open(entry["path"], "rb") as handle:
        source = handle.read()
    payload = marshal.dumps(compile(source, "<frozen " + name + ">", "exec", dont_inherit=True))
    ident = name.replace(".", "_")
    blocks.append(
        "static const unsigned char taffy_frozen_" + ident + "[] = {"
        + ",".join(str(byte) for byte in payload) + "};")
    rows.append('    {"%s", taffy_frozen_%s, %d, %d},'
                % (name, ident, len(payload), 1 if entry["package"] else 0))

with open(sys.argv[2], "w") as out:
    out.write("// Generated by taffy-core/third_party/cpython/tools/freeze_modules.py.\n")
    out.write("// Marshalled by CPython %s. Do not edit.\n\n" % sys.version.split()[0])
    out.write("\n".join(blocks))
    out.write("\n\nstatic const struct _frozen taffy_frozen_extra[] = {\n")
    out.write("\n".join(rows))
    out.write("\n    {0, 0, 0, 0}\n};\n")

print(json.dumps({"modules": len(rows),
                  "bytes": sum(len(block) for block in blocks)}))
'''


def build_spec(library: str, bootstrap: str) -> dict[str, dict]:
    """Resolves every frozen module to a file, or names the ones that are not."""
    runtime = os.path.dirname(bootstrap)
    spec = {
        name: {"path": bootstrap if name == "taffy_stdlib_boot" else os.path.join(runtime, path),
               "package": False}
        for name, path in FIRST_PARTY_MODULES.items()
    }
    for name, (relative, _reason) in STARTUP_MODULES.items():
        spec[name] = {
            "path": os.path.join(library, relative),
            "package": name in PACKAGES,
        }
    return spec


def spec_findings(spec: dict[str, dict]) -> list[str]:
    """Whether every module in the spec is a file that exists."""
    return [f"{name}: {entry['path']} does not exist"
            for name, entry in spec.items() if not os.path.isfile(entry["path"])]


def interpreter_version(build_python: str) -> str:
    """The `major.minor.patch` of the interpreter that would marshal."""
    completed = subprocess.run(
        [build_python, "-c", "import sys; print('.'.join(map(str, sys.version_info[:3])))"],
        capture_output=True, text=True, check=True,
    )
    return completed.stdout.strip()


def version_findings(pinned: str, found: str) -> list[str]:
    """Whether the marshalling interpreter is the one the pin names."""
    if pinned == found:
        return []
    return [
        f"the build interpreter is CPython {found} and the pin is {pinned}; a code "
        "object marshalled by one and read by the other fails on its first frozen "
        "import with an error naming the module rather than the mismatch"
    ]


def pinned_version(manifest: str) -> str:
    with open(manifest, encoding="utf-8") as handle:
        return json.load(handle)["upstream"]["version"]


def freeze(build_python: str, spec: dict[str, dict], output: str) -> dict:
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as handle:
        json.dump(spec, handle)
        spec_path = handle.name
    try:
        completed = subprocess.run(
            [build_python, "-c", _CHILD, spec_path, output],
            capture_output=True, text=True, check=False,
        )
    finally:
        os.unlink(spec_path)
    if completed.returncode != 0:
        raise SystemExit(f"freezing failed:\n{completed.stderr.strip()}")
    return json.loads(completed.stdout)


def _self_test() -> int:
    checks: list[tuple[str, bool]] = []

    def check(name: str, condition: bool) -> None:
        checks.append((name, condition))

    check("the bootstrap is the first frozen module",
          next(iter(FIRST_PARTY_MODULES)) == "taffy_stdlib_boot")
    check("the entrypoint registry is frozen",
          "taffy_python_tools" in FIRST_PARTY_MODULES)
    check("every startup module states a reason",
          all(reason for _path, reason in STARTUP_MODULES.values()))
    check("every package is a startup module", PACKAGES <= set(STARTUP_MODULES))

    check("a matching interpreter passes", not version_findings("3.14.7", "3.14.7"))
    check("a different patch release is refused", bool(version_findings("3.14.7", "3.14.6")))
    check("a different minor release is refused", bool(version_findings("3.14.7", "3.13.9")))

    runtime = runpy.run_path(os.path.join(RUNTIME, "taffy_python_tools.py"))
    execute = runtime["execute"]
    document_request = json.dumps({
        "document": {
            "title": "Quarterly report",
            "sections": [{"heading": "Summary", "paragraphs": ["Ready"]}],
        }
    }).encode()
    document = execute("document.build", document_request)
    spreadsheet_request = json.dumps({"sheet_name": "Results", "csv": "Name,Value\nA,1"}).encode()
    spreadsheet = execute("spreadsheet.build", spreadsheet_request)
    check("document.build emits a complete deterministic ZIP",
          document.startswith(b"PK\x03\x04")
          and document.rfind(b"PK\x05\x06") == len(document) - 22
          and document == execute("document.build", document_request))
    check("spreadsheet.build emits a complete deterministic ZIP",
          spreadsheet.startswith(b"PK\x03\x04")
          and spreadsheet.rfind(b"PK\x05\x06") == len(spreadsheet) - 22
          and spreadsheet == execute("spreadsheet.build", spreadsheet_request))
    try:
        execute("document.build", document_request.replace(b"report", b"report\\u0001"))
        check("XML-forbidden text is refused before an artifact is emitted", False)
    except ValueError:
        check("XML-forbidden text is refused before an artifact is emitted", True)
    try:
        execute("model-authored.module", b"{}")
        check("an unregistered entrypoint is refused", False)
    except ValueError:
        check("an unregistered entrypoint is refused", True)
    malformed_csv = json.dumps({"sheet_name": "Results", "csv": 'Name\n"value"junk'}).encode()
    try:
        execute("spreadsheet.build", malformed_csv)
        check("non-RFC bytes after a quoted cell are refused", False)
    except ValueError:
        check("non-RFC bytes after a quoted cell are refused", True)
    duplicate_sheets = json.dumps({
        "workbook": {"sheets": [
            {"name": "Data", "columns": ["Value"]},
            {"name": "data", "columns": ["Value"]},
        ]},
        "rows": {"Data": "1", "data": "2"},
    }).encode()
    try:
        execute("spreadsheet.build", duplicate_sheets)
        check("case-insensitive duplicate sheet names are refused", False)
    except ValueError:
        check("case-insensitive duplicate sheet names are refused", True)

    with tempfile.TemporaryDirectory() as directory:
        library = os.path.join(directory, "Lib")
        for relative, _reason in STARTUP_MODULES.values():
            path = os.path.join(library, relative)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as handle:
                handle.write("VALUE = 1\n")
        bootstrap = os.path.join(directory, "taffy_stdlib_boot.py")
        with open(bootstrap, "w", encoding="utf-8") as handle:
            handle.write("def install(buffer):\n    return 0\n")
        with open(os.path.join(directory, "taffy_python_tools.py"), "w", encoding="utf-8") as handle:
            handle.write("def execute(entrypoint, payload):\n    return payload\n")

        spec = build_spec(library, bootstrap)
        check("a complete tree resolves", not spec_findings(spec))
        check("every module is in the spec",
              len(spec) == len(STARTUP_MODULES) + len(FIRST_PARTY_MODULES))
        check("`encodings` is marked a package", spec["encodings"]["package"] is True)
        check("a module is not", spec["types"]["package"] is False)

        os.unlink(os.path.join(library, "types.py"))
        check("a missing module is refused", bool(spec_findings(build_spec(library, bootstrap))))
        with open(os.path.join(library, "types.py"), "w", encoding="utf-8") as handle:
            handle.write("VALUE = 1\n")

        # The host interpreter marshals in its own format, which is why a real
        # run refuses one that is not the pin. Here only the shape is under
        # test, and the shape does not depend on the format.
        header = os.path.join(directory, "taffy_frozen.h")
        result = freeze(sys.executable, build_spec(library, bootstrap), header)
        with open(header, encoding="utf-8") as handle:
            emitted = handle.read()
        check("every module is emitted",
              result["modules"] == len(STARTUP_MODULES) + len(FIRST_PARTY_MODULES))
        check("the table is terminated", "{0, 0, 0, 0}" in emitted)
        check("the table is extra rows only, never a substitution",
              "PyImport_FrozenModules" not in emitted)
        rows = dict(re.findall(r'\{"([\w.]+)", taffy_frozen_\w+, \d+, (\d)\}', emitted))
        check("a package carries its flag", rows.get("encodings") == "1")
        check("a module carries none", rows.get("types") == "0")
        check("a dotted name becomes a C identifier", "taffy_frozen_encodings_utf_8" in emitted)
        check("no path is emitted", library not in emitted)
        check("the marshalling interpreter is recorded", "Marshalled by CPython" in emitted)

        broken = os.path.join(directory, "broken.py")
        with open(broken, "w", encoding="utf-8") as handle:
            handle.write("def (\n")
        try:
            freeze(sys.executable, {"broken": {"path": broken, "package": False}}, header)
            check("a module that does not compile is refused", False)
        except SystemExit:
            check("a module that does not compile is refused", True)

    failed = [name for name, passed in checks if not passed]
    for name, passed in checks:
        print(f"{'ok  ' if passed else 'FAIL'} {name}")
    print(f"{len(checks) - len(failed)}/{len(checks)} rules hold")
    return 1 if failed else 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--library", help="a CPython Lib/ directory at the pinned version")
    parser.add_argument("--build-python", help="a CPython of the pinned version, for this host")
    parser.add_argument("--bootstrap", default=os.path.join(RUNTIME, "taffy_stdlib_boot.py"),
                        help="the bootstrap to freeze (default: the one beside this tool)")
    parser.add_argument("--manifest", default=os.path.join(HERE, "manifest.json"),
                        help="the pin the build interpreter is checked against")
    parser.add_argument("--output", help="where to write the generated header")
    parser.add_argument("--self-test", action="store_true",
                        help="drive every rule over a synthetic tree, refusals included")
    args = parser.parse_args(argv)

    if args.self_test:
        return _self_test()
    missing = [name for name in ("library", "build_python", "output") if not getattr(args, name)]
    if missing:
        parser.error("required: " + ", ".join(f"--{name.replace('_', '-')}" for name in missing))

    findings = version_findings(pinned_version(args.manifest),
                               interpreter_version(args.build_python))
    spec = build_spec(args.library, args.bootstrap)
    findings += spec_findings(spec)
    if findings:
        raise SystemExit("\n".join(findings))
    print(json.dumps(freeze(args.build_python, spec, args.output), indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())
